mapper.select:
SELECT d.id AS currency_pair_definition_id, bc.code AS base_currency_code, qc.code AS quote_currency_code, d.`precision` AS `precision`, b.id AS brand_id, b.code AS brand_code, er.rate, er.deposit_rate, er.withdrawal_rate, er.rate_minute, er.source FROM currency_pair_definition d CROSS JOIN brand b JOIN currency bc ON bc.id = d.base_currency_id JOIN currency qc ON qc.id = d.quote_currency_id LEFT JOIN ( SELECT e.currency_pair_definition_id, e.brand_id, e.rate, e.deposit_rate, e.withdrawal_rate, e.rate_minute, e.source, ROW_NUMBER() OVER (PARTITION BY e.currency_pair_definition_id, e.brand_id ORDER BY e.rate_minute DESC) AS rn FROM exchange_rate e ) er ON er.currency_pair_definition_id = d.id AND er.brand_id = b.id AND er.rn = 1
AND b.id = #{brandId}
ORDER BY d.id, b.id
